}

void solve() {
    int n; cin >> n;
    input(vec, 3*n);
    sort(all(vec));
    vector<int>pre(3*n); pre[0] = vec[0];
    for (int i = 1; i < 3 * n; i++) pre[i] = pre[i-1] + vec[i];
    auto qry = [&] (int l, int r) -> int {
        if (l > r) return 0;
        return pre[r] - pre[l] + vec[l];
    };
    int total = 6 * qry(2*n, 3*n-1);
    for (int i = 0; i < n; i++) {
        int l = 2 * i, r = 3 * n - i - 1;
        int left = 0, right = n - i - 1, ans = 0;
        while (left <= right) {
            int mid = (left + right)>>1ll;
            int r_idx = r - (2 * mid);
            int xy = vec[r_idx-1] + vec[r_idx];
            int z = vec[l+mid];
            if (xy - (3*z) > 0) {
                ans = mid + 1;
                left = mid + 1;
            }
            else {
                right = mid - 1;
            }
        }
        int temp = 6 * qry(3*n-i, 3*n-1);
        int diff_idx = r - (2 * ans);
        temp += qry(diff_idx + 1, r) * 4;
        temp += qry(l + ans, diff_idx) * 3;
        total = max(total, temp);
    }
    cout << total << endl;
}

int32_t main() {
    cin.sync_with_stdio(false); cin.tie(0); cout.tie(0);
    int t; cin >> t;
    while (t--) solve();
    return 0;
}
